#!/usr/bin/env -S uv run --script
# Synced from bootstrap: repo/tools/mise/tasks/setup-mise.py. Do not edit this file.
# The next sync writes it again, and each change in this file is lost.
# /// script
# requires-python = ">=3.14"
# dependencies = []
# ///
# MISE description="Setup MISE: reshim, doctor, install; --upgrade also upgrades"
# MISE hide=true
# MISE tools={uv="latest", python="3.14"}

# USAGE flag "--upgrade" help="also upgrade the installed tools"

import os
import subprocess
import sys

sys.dont_write_bytecode = True
sys.path.insert(0, f"{os.environ['MISE_PROJECT_ROOT']}/.config/mise/tasks/_scripts")
import helpers  # noqa: E402


def run(*cmd, **kwargs):
  """Run the command. When it fails, stop the task with its code."""
  rc = subprocess.run(cmd, check=False, **kwargs).returncode
  if rc:
    sys.exit(128 - rc if rc < 0 else rc)


def main():
  helpers.print_header("Setting up MISE ...")

  # Reshim mise to ensure all tools are available
  helpers.print_subheader("Reshimming mise ...")
  run("mise", "reshim")

  # Run mise doctor
  helpers.print_subheader("Running mise doctor ...")
  run("mise", "doctor", "--quiet", "--silent", stdout=subprocess.DEVNULL)

  # Install mise tools, and upgrade them only on request
  helpers.print_subheader("Installing mise tools ...")
  run("mise", "install", "--yes", "--jobs", "10")
  if os.environ.get("usage_upgrade", "false") == "true":
    helpers.print_subheader("Upgrading mise tools ...")
    run("mise", "upgrade", "--yes", "--jobs", "10", "--local")


if __name__ == "__main__":
  main()
